with lines as (select id, plan, effective_from, currency, tier_value from price_tiers lateral view explode(discounts) x as tier_value) select case when tier_value >= 75 then 'HIGH' else 'LOW' end as tier_value_tier, plan, approx_percentile(tier_value, 0.95) as tier_value_p95, count_if(plan = 'starter') as starter_events from lines group by rollup (case when tier_value >= 75 then 'HIGH' else 'LOW' end, plan) order by tier_value_p95 desc;
